+  if (!(stdoutBytes instanceof Uint8Array)) return null;
+  let text;
+  try {
+    text = new TextDecoder("utf-8", { fatal: true }).decode(stdoutBytes);
+  } catch {
+    return null;
+  }
+  const lines = text.replace(/\r\n/gu, "\n").split("\n");
+  if (lines.at(-1) === "") lines.pop();
+  if (lines.some((line) => line.trimStart().startsWith("Bail out!"))) {
+    return null;
+  }
+  const tapHeaderIndexes = lines
+    .map((line, index) => (line === "TAP version 13" ? index : null))
+    .filter((value) => value !== null);
+  if (
+    tapHeaderIndexes.length !== 1 ||
+    lines
+      .slice(0, tapHeaderIndexes[0])
+      .some((line) => parseTapStructuralLine(line) !== null)
+  ) {
+    return null;
+  }
+  const parsed =
+    parseTapScope(lines, tapHeaderIndexes[0] + 1, 0);
+  const footer =
+    parsed === null ? [] : lines.slice(parsed.nextIndex);
+  if (
+    tapHeaderIndexes.length !== 1 ||
+    parsed === null ||
+    footer.length !== 8 ||
+    !/^# tests [0-9]+$/u.test(footer[0] ?? "") ||
+    !/^# suites [0-9]+$/u.test(footer[1] ?? "") ||
+    !/^# pass [0-9]+$/u.test(footer[2] ?? "") ||
+    !/^# fail [0-9]+$/u.test(footer[3] ?? "") ||
+    !/^# cancelled [0-9]+$/u.test(footer[4] ?? "") ||
+    !/^# skipped [0-9]+$/u.test(footer[5] ?? "") ||
+    !/^# todo [0-9]+$/u.test(footer[6] ?? "") ||
+    !/^# duration_ms [0-9]+(?:\.[0-9]+)?$/u.test(footer[7] ?? "")
+  ) {
+    return null;
+  }
+  const counts = {};
+  const footerIndexByField = {
+    tests: 0,
+    pass: 2,
+    fail: 3,
+    cancelled: 4,
+    skipped: 5,
+    todo: 6,
+  };
+  for (const field of TAP_COUNT_FIELDS) {
+    const match = new RegExp(`^# ${field} ([0-9]+)$`, "u").exec(
+      footer[footerIndexByField[field]],
+    );
+    if (match === null) return null;
+    counts[field] = Number(match[1]);
+    if (
+      !Number.isSafeInteger(counts[field]) ||
+      counts[field] < 0 ||
+      counts[field] > 1_000_000
+    ) {
+      return null;
+    }
+  }
+  const derivedCounts = {
+    tests: parsed.points.length,
+    pass: 0,
+    fail: 0,
+    cancelled: 0,
+    skipped: 0,
+    todo: 0,
+  };
+  for (const point of parsed.points) {
+    derivedCounts[point.outcome] += 1;
+  }
+  const skippedTestNames = sortedUtf8Strings(
+    parsed.points
+      .filter((point) => point.outcome === "skipped")
+      .map((point) => point.name),
+  );
+  if (
+    TAP_COUNT_FIELDS.some(
+      (field) => counts[field] !== derivedCounts[field],
+    ) ||
+    counts.tests !==
+      counts.pass +
+        counts.fail +
+        counts.cancelled +
+        counts.skipped +
+        counts.todo ||
+    skippedTestNames.length !== counts.skipped ||
+    !validTapTestNames(skippedTestNames)
+  ) {
+    return null;
+  }
+  return {
+    format: "NODE_TEST_TAP",
+    ...counts,
+    skippedTestNames,
+    skippedTestSetSha256: await sha256ProjectValue(skippedTestNames),
+  };
+}
+
+export async function tapSummaryMatchesExpectation(summary, expectation) {
+  return (
+    keysExactly(summary, TAP_SUMMARY_KEYS) &&
+    (await validTapExpectation(expectation)) &&
+    summary.format === expectation.format &&
+    TAP_COUNT_FIELDS.every(
+      (field) => summary[field] === expectation[field],
+    ) &&
+    validTapTestNames(summary.skippedTestNames) &&
+    summary.skippedTestSetSha256 ===
+      (await sha256ProjectValue(summary.skippedTestNames)) &&
+    canonicalizeProjectJson(summary.skippedTestNames) ===
+      canonicalizeProjectJson(expectation.allowedSkippedTestNames) &&
+    summary.skippedTestSetSha256 ===
+      expectation.allowedSkippedTestSetSha256
+  );
+}
