+export async function validateIndependentReviewTestPlan(plan) {
+  if (
+    !keysExactly(plan, [
+      "schemaVersion",
+      "planId",
+      "commands",
+      "planSha256",
+    ]) ||
+    plan.schemaVersion !== "independent-review-test-plan.v2" ||
+    !COMMAND_ID.test(plan.planId ?? "") ||
