    !Array.isArray(receipt.reviewedPaths) ||
    receipt.reviewedPaths.length === 0 ||
    new Set(receipt.reviewedPaths).size !== receipt.reviewedPaths.length ||
    !receipt.reviewedPaths.every(validPath) ||
