    schemaVersion: k3
      ? "independent-review-material.v3"
      : "independent-review-material.v2",
    materialId: input.materialId,
    source: {
      baseCommit: bundle.source.baseCommit,
      sourceCommit: bundle.source.sourceCommit,
      sourceTree: bundle.source.tree,
