      canonicalOutputSchema: byteBinding(
        fixedPaths.outputSchema,
        outputSchemaBytes,
      ),
      canonicalReceiptSchema: byteBinding(
        fixedPaths.receiptSchema,
        receiptSchemaBytes,
      ),
