        subjectCommit: subjectCommitText.trim(),
        subjectTree: subjectTreeText.trim(),
        anchor: changed,
        executingBootstrapPath: bootstrapPath,
        executingLauncherPath: launcherPath,
      }),
      /RUNTIME_TRUST_NOT_PROVED/u,
    );
  }
});

