    assert.ok(pulls <= 2);
    assert.equal(Object.hasOwn(result, "responseBytes"), false);
  }

  let announcedLengthCancelled = false;
  const announcedTooLarge = {
    status: 200,
    redirected: false,
    url: "https://api.moonshot.ai/v1/chat/completions",
